import { BindingModel } from '.';

export class Util {

    /**
     * Extracts the name of a variable returned by the passed function.
     * e.g. getVariableName(() => this.model.myVariable) will return "myVariable"
     * getVariableName(function() { return this.model.myVariable; }) will return "myVariable"
     * @param func A simple function that returns a variable from a model.
     * @param addLocalIdentifier Whether to add a predefined local identifier prefix. e.g. "_myVariable".
     * Defined by BindingModel.LOCAL_MODEL_VALUE_IDENTIFIER.
     * @returns The extracted variable name.
     */
    public static getVariableName<TResult>(func: () => TResult, addLocalIdentifier?: boolean): string {
        const varExtractor: RegExp = /\.([^.;}\s]+)[;\s}]*$/;

        const funcString: string = func.toString();
        const extractedArray: RegExpExecArray | null = varExtractor.exec(funcString);
        if (extractedArray == null) { throw new Error(`BindingModel: Error extracting returned variable name from "${funcString}", expected format like: "() => this.object.myVariable" or "function() { return this.object.myVariable; }"`); }

        const extractedString: string = extractedArray[1].replace(';', '').trim();

        return addLocalIdentifier ? BindingModel.LOCAL_MODEL_VALUE_IDENTIFIER + extractedString : extractedString;
    }
}
